comments.body:
`unpacker_parse_header` doesn't update Unpacker's `read_ptr` and `read_size` in case of an error, any invalid header should crash nvim 
This patch seems to fix the issue:
```diff
diff --git a/src/nvim/msgpack_rpc/unpacker.c b/src/nvim/msgpack_rpc/unpacker.c
index c3b1022db..d14d06f95 100644
--- a/src/nvim/msgpack_rpc/unpacker.c
+++ b/src/nvim/msgpack_rpc/unpacker.c
@@ -202,13 +202,10 @@ bool unpacker_parse_header(Unpacker *p)
   mpack_token_t tok;
   int result;
 
-  const char *data = p->read_ptr;
-  size_t size = p->read_size;
-
   assert(!ERROR_SET(&p->unpack_error));
 
 #define NEXT(tok) \
-  result = mpack_read(&p->reader, &data, &size, &tok); \
+  result = mpack_read(&p->reader, &p->read_ptr, &p->read_size, &tok); \
   if (result) { goto error; }
 
   NEXT(tok);
@@ -257,8 +254,6 @@ bool unpacker_parse_header(Unpacker *p)
                                              tok.length, &p->unpack_error);
   }
 
-  p->read_ptr = data;
-  p->read_size = size;
   return true;
 #undef NEXT
 
```

ok, I think this might just be an overzealous assert. There's nothing wrong with not consuming anything after receiving some input:
```diff
diff --git a/src/nvim/rbuffer.c b/src/nvim/rbuffer.c
index ef286b3e22..493c079d4c 100644
--- a/src/nvim/rbuffer.c
+++ b/src/nvim/rbuffer.c
@@ -123,7 +123,10 @@ char *rbuffer_read_ptr(RBuffer *buf, size_t *read_count) FUNC_ATTR_NONNULL_ALL
 void rbuffer_consumed(RBuffer *buf, size_t count)
   FUNC_ATTR_NONNULL_ALL
 {
-  assert(count && count <= buf->size);
+  if (count == 0) {
+    return;
+  }
+  assert(count <= buf->size);
```
